const puppeteer = require("puppeteer");

// Helper function to convert number to words (Indian Rupee System)
function numberToWords(num) {
    if (num === 0) return 'Zero Rupees Only';
    const a = ['', 'One ', 'Two ', 'Three ', 'Four ', 'Five ', 'Six ', 'Seven ', 'Eight ', 'Nine ', 'Ten ', 'Eleven ', 'Twelve ', 'Thirteen ', 'Fourteen ', 'Fifteen ', 'Sixteen ', 'Seventeen ', 'Eighteen ', 'Nineteen '];
    const b = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];

    if (num.toString().length > 9) return 'Overflow';
    const n = ('000000000' + num).substr(-9).match(/^(\d{2})(\d{2})(\d{2})(\d{1})(\d{2})$/);
    if (!n) return;
    let str = '';
    str += (n[1] != 0) ? (a[Number(n[1])] || b[n[1][0]] + ' ' + a[n[1][1]]) + 'Crore ' : '';
    str += (n[2] != 0) ? (a[Number(n[2])] || b[n[2][0]] + ' ' + a[n[2][1]]) + 'Lakh ' : '';
    str += (n[3] != 0) ? (a[Number(n[3])] || b[n[3][0]] + ' ' + a[n[3][1]]) + 'Thousand ' : '';
    str += (n[4] != 0) ? (a[Number(n[4])] || b[n[4][0]] + ' ' + a[n[4][1]]) + 'Hundred ' : '';
    str += (n[5] != 0) ? ((str != '') ? 'and ' : '') + (a[Number(n[5])] || b[n[5][0]] + ' ' + a[n[5][1]]) : '';
    return str.trim() + ' Rupees Only';
}

exports.generateQuotationPDF = async (quotation, settings) => {
    try {
        const browser = await puppeteer.launch({
            headless: "new",
            args: [
                "--no-sandbox",
                "--disable-setuid-sandbox",
                "--disable-dev-shm-usage",
                "--disable-gpu",
                "--no-zygote"
            ]
        });
        const page = await browser.newPage();

        const lead = quotation.lead || {};
        const qDate = new Date(quotation.createdAt).toLocaleDateString('en-GB');

        let calcSubTotal = 0;
        let taxAmount = 0;
        let productTotal = 0;
        let serviceTotal = 0;

        // Generate Main Table Items
        let itemsHtml = "";
        let taxItemsHtml = "";

        // --- Separate products and services ---
        const productItems = quotation.items.filter(item => !(item.itemType === 'Service' || item.itemId?.itemType === 'Service'));
        const serviceItems = quotation.items.filter(item => item.itemType === 'Service' || item.itemId?.itemType === 'Service');

        // Calculate product group totals
        let prodSubTotal = 0, prodGstAmt = 0;
        productItems.forEach(item => {
            const qty = item.quantity || 1;
            const price = item.price || 0;
            const gstPerc = item.gstPercentage || 18;
            const val = qty * price;
            prodSubTotal += val;
            prodGstAmt += (val * gstPerc) / 100;
        });
        const prodTotalWithGst = prodSubTotal + prodGstAmt;
        productTotal = prodTotalWithGst;

        // Calculate service group totals
        let svcSubTotal = 0, svcGstAmt = 0;
        serviceItems.forEach(item => {
            const qty = item.quantity || 1;
            const price = item.price || 0;
            const gstPerc = item.gstPercentage || 18;
            const val = qty * price;
            svcSubTotal += val;
            svcGstAmt += (val * gstPerc) / 100;
        });
        const svcTotalWithGst = svcSubTotal + svcGstAmt;
        serviceTotal = svcTotalWithGst;

        calcSubTotal = prodSubTotal + svcSubTotal;
        taxAmount = prodGstAmt + svcGstAmt;

        // Determine GST rate label
        const prodGstRates = [...new Set(productItems.map(i => i.gstPercentage || 18))];
        const svcGstRates = [...new Set(serviceItems.map(i => i.gstPercentage || 18))];
        const prodGstLabel = prodGstRates.length === 1 ? prodGstRates[0] + '%' : 'Various';
        const svcGstLabel = svcGstRates.length === 1 ? svcGstRates[0] + '%' : 'Various';

        // Product & Service names (comma separated)
        const productNames = productItems.map(i => i.name || i.itemId?.name || 'Item').join(', ');
        const serviceNames = serviceItems.map(i => i.name || i.itemId?.name || 'Item').join(', ');

        // Build main items table (one row per item - unchanged)
        quotation.items.forEach((item, index) => {
            const qty = item.quantity || 1;
            const price = item.price || 0;
            const gstPerc = item.gstPercentage || 18;
            itemsHtml += `
                <tr style="height: 30px;">
                    <td style="width: 8%; text-align: center; vertical-align: top;">${index + 1}</td>
                    <td style="width: 43%; padding-left: 10px; vertical-align: top;">
                        <strong>${item.name || item.itemId?.name || 'Item'}</strong><br/>
                        <span style="font-size: 10px;">${item.description || item.itemId?.description || ''}</span>
                    </td>
                    <td style="width: 16%; text-align: center; padding-right: 15px; vertical-align: top;">${qty}</td>
                    <td style="width: 10%; text-align: center; vertical-align: top;">${gstPerc}%</td>
                    ${index === 0 ? `<td rowspan="${quotation.items.length}" style="width: 23%; text-align: center; vertical-align: middle; font-weight: bold; font-size: 20px;">${(quotation.totalAmount || 0).toFixed(2)}</td>` : ''}
                </tr>
            `;
        });

        // Build TAX BREAKUP table - only 2 grouped rows
        if (productItems.length > 0) {
            taxItemsHtml += `
                <tr style="height: 30px;">
                    <td style="width: 7%; text-align: center; vertical-align: bottom; padding-bottom: 3px; font-size: 13px;">1</td>
                    <td style="width: 28%; padding-left: 10px; font-weight: bold; vertical-align: bottom; padding-bottom: 3px; font-size: 13px;">Product</td>
                    <td style="width: 16%; text-align: center; vertical-align: bottom; padding-bottom: 3px; font-size: 13px;">${prodSubTotal.toFixed(2)}</td>
                    <td style="width: 14%; text-align: center; vertical-align: bottom; padding-bottom: 3px; font-size: 13px;">${prodGstLabel}</td>
                    <td style="width: 15%; text-align: center; vertical-align: bottom; padding-bottom: 3px; font-size: 13px;">${prodGstAmt.toFixed(2)}</td>
                    <td style="width: 20%; text-align: right; padding-right: 15px; vertical-align: bottom; padding-bottom: 3px; font-size: 13px;">${prodTotalWithGst.toFixed(2)}</td>
                </tr>
            `;
        }
        if (serviceItems.length > 0) {
            taxItemsHtml += `
                <tr style="height: 30px;">
                    <td style="width: 7%; text-align: center; vertical-align: bottom; padding-bottom: 3px; font-size: 13px;">${productItems.length > 0 ? 2 : 1}</td>
                    <td style="width: 28%; padding-left: 10px; font-weight: bold; vertical-align: bottom; padding-bottom: 3px; font-size: 13px;">Service</td>
                    <td style="width: 16%; text-align: center; vertical-align: bottom; padding-bottom: 3px; font-size: 13px;">${svcSubTotal.toFixed(2)}</td>
                    <td style="width: 14%; text-align: center; vertical-align: bottom; padding-bottom: 3px; font-size: 13px;">${svcGstLabel}</td>
                    <td style="width: 15%; text-align: center; vertical-align: bottom; padding-bottom: 3px; font-size: 13px;">${svcGstAmt.toFixed(2)}</td>
                    <td style="width: 20%; text-align: right; padding-right: 15px; vertical-align: bottom; padding-bottom: 3px; font-size: 13px;">${svcTotalWithGst.toFixed(2)}</td>
                </tr>
            `;
        }

        const totalAmount = calcSubTotal + taxAmount;
        const totalAmountWords = numberToWords(Math.round(totalAmount));

        // TO-DO FOR USER: 
        // Convert the blank estimate image to base64 and paste it here, OR use an absolute URL.
        // E.g. 'data:image/jpeg;base64,/9j/4AAQSkZJRgABAQ...' 
        // You can use a site like https://www.base64-image.de/ to convert your image.
        const backgroundImageUrl = "";

        const htmlContent = `
            <!DOCTYPE html>
            <html>
            <head>
                <meta charset="UTF-8">
                <style>
                    @import url('https://fonts.googleapis.com/css2?family=Roboto:wght@500;700&display=swap');
                    body {
                        margin: 0;
                        padding: 0;
                        font-family: 'Roboto', sans-serif;
                        color: #000;
                        font-size: 13px;
                    }
                    /* Container exactly matches A4 aspect ratio */
                    .a4-container {
                        width: 794px;
                        height: 1122px; 
                        position: relative;
                        background-image: url('data:image/png;base64,${backgroundImageUrl}');
                        background-size: 100% 100%;
                        background-repeat: no-repeat;
                    }
                    
                    /* ABSOLUTE POSITIONED ELEMENTS */
                    .estimate-no { position: absolute; top: 192px; left: 645px; font-weight: bold; font-size: 12px; }
                    .estimate-date { position: absolute; top: 211px; left: 645px; font-weight: bold; font-size: 12px; }
                    
                    .bill-to { position: absolute; top: 233px; left: 95px; font-weight: bold; font-size: 14px; width: 600px;}
                    
                    /* Main Table Data Container */
                    .main-items { position: absolute; top: 305px; left: 25px; width: 743px; }
                    .main-items table { width: 100%; border-collapse: collapse; }
                    .main-items td { border: none; padding-top: 2px; padding-bottom: 2px; }
                    .main-items tr:last-child td { border-bottom: none; }

                     /* Product & Service Names in Row A and B */
                     .row-a-name { position: absolute; top: 560px; left: 90px; width: 490px; font-weight: bold; font-size: 13px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
                     .row-b-name { position: absolute; top: 588px; left: 90px; width: 490px; font-weight: bold; font-size: 13px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }

                    /* Totals A & B */
                    .total-a { position: absolute; top: 558px; left: 590px; width: 160px; text-align: right; padding-right: 15px; font-weight: bold; font-size: 13px; }
                    .total-b { position: absolute; top: 586px; left: 590px; width: 160px; text-align: right; padding-right: 15px; font-weight: bold; font-size: 13px; }
                    .total-ab { position: absolute; top: 613px; left: 590px; width: 160px; text-align: right; padding-right: 15px; font-weight: bold; font-size: 14px; }

                    /* Tax Breakup Data Container */
                    .tax-items { position: absolute; top: 721px; left: 25px; width: 743px; }
                    .tax-items table { width: 100%; border-collapse: collapse; table-layout: fixed; }
                    .tax-items td { border: none; padding-top: 2px; padding-bottom: 2px; font-size: 13px; overflow: hidden; }
                    .tax-items tr:last-child td { border-bottom: none; }
                    
                    .tax-subtotal { position: absolute; top: 805px; left: 320px; width: 130px; text-align: center; font-weight: bold;}
                    .tax-gst { position: absolute; top: 805px; left: 545px; width: 95px; text-align: center; font-weight: bold;}
                    .tax-total { position: absolute; top: 805px; left: 640px; width: 130px; text-align: right; padding-right:15px; font-weight: bold;}

                    .amount-words { display: none; }

                    /* Account Details Section */
                    .acc-name  { position: absolute; top: 1032px; left: 148px; font-size: 9px; font-weight: bold; }
                    .acc-no    { position: absolute; top: 1048px; left: 148px; font-size: 9px; font-weight: bold; }
                    .acc-ifsc  { position: absolute; top: 1064px; left: 148px; font-size: 9px; font-weight: bold; }
                    .acc-branch{ position: absolute; top: 1080px; left: 148px; font-size: 9px; font-weight: bold; }
                    .acc-type  { position: absolute; top: 1096px; left: 148px; font-size: 9px; font-weight: bold; }

                    /* We can leave the signature/warranty empty as it's static in the template image */
                </style>
            </head>
            <body>
                <div class="a4-container">
                    <!-- Overlay Data -->
                    <div class="estimate-no">${quotation.quotationNumber}</div>
                    <div class="estimate-date">${qDate}</div>
                    
                    <div class="bill-to">
                        ${lead.customerName || ''} ${lead.companyName ? ' - ' + lead.companyName : ''}
                    </div>

                    <div class="main-items">
                        <table>
                            ${itemsHtml}
                        </table>
                    </div>

                    <div class="row-a-name">${productNames}</div>
                    <div class="row-b-name">${serviceNames}</div>
                    <div class="total-a">${productTotal.toFixed(2)}</div>
                    <div class="total-b">${serviceTotal.toFixed(2)}</div>
                    <div class="total-ab">${(quotation.totalAmount || totalAmount || 0).toFixed(2)}</div>

                    <div class="tax-items">
                        <table>
                            ${taxItemsHtml}
                        </table>
                    </div>

                    <div class="tax-subtotal">${calcSubTotal.toFixed(2)}</div>
                    <div class="tax-gst">${taxAmount.toFixed(2)}</div>
                    <div class="tax-total">${(quotation.totalAmount || totalAmount || 0).toFixed(2)}</div>

                    

                    
                    
                    

                    <div class="amount-words">${totalAmountWords}</div>
                    <div class="acc-name">${settings?.bankAccountName || ''}</div>
                    <div class="acc-no">${settings?.bankAccountNumber || ''}</div>
                    <div class="acc-ifsc">${settings?.bankIfsc || ''}</div>
                    <div class="acc-branch">${settings?.bankBranch || ''}</div>
                    <div class="acc-type">${settings?.bankAccountType || ''}</div>
                </div>
            </body>
            </html>
        `;

        await page.setContent(htmlContent, { waitUntil: 'networkidle0', timeout: 300000 });

        const pdfBuffer = await page.pdf({
            format: 'A4',
            printBackground: true,
            margin: { top: '0', right: '0', bottom: '0', left: '0' } // 0 margin to fit the image perfectly
        });

        await browser.close();
        return pdfBuffer;
    } catch (error) {
        console.error("Error generating PDF:", error);
        throw error;
    }
};


exports.generateQuotationImage = async (quotation, settings) => {
    try {
        const browser = await puppeteer.launch({
            headless: "new",
            args: [
                "--no-sandbox",
                "--disable-setuid-sandbox",
                "--disable-dev-shm-usage",
                "--disable-gpu",
                "--no-zygote"
            ]
        });
        const page = await browser.newPage();

        const lead = quotation.lead || {};
        const qDate = new Date(quotation.createdAt).toLocaleDateString('en-GB');

        let calcSubTotal = 0;
        let taxAmount = 0;
        let productTotal = 0;
        let serviceTotal = 0;

        // Generate Main Table Items
        let itemsHtml = "";
        let taxItemsHtml = "";

        quotation.items.forEach((item, index) => {
            const qty = item.quantity || 1;
            const price = item.price || 0;
            const gstPerc = item.gstPercentage || 18;

            const valueBeforeGst = qty * price;
            const gstAmt = (valueBeforeGst * gstPerc) / 100;
            const totalWithGst = valueBeforeGst + gstAmt;

            calcSubTotal += valueBeforeGst;
            taxAmount += gstAmt;
            if (item.itemType === 'Service' || item.itemId?.itemType === 'Service') {
                serviceTotal += totalWithGst;
            } else {
                productTotal += totalWithGst;
            }

            // HTML for items without borders, perfectly aligned for the background image
            itemsHtml += `
                <tr style="height: 30px;">
                    <td style="width: 8%; text-align: center; vertical-align: top;">${index + 1}</td>
                    <td style="width: 43%; padding-left: 10px; vertical-align: top;">
                        <strong>${item.name || item.itemId?.name || 'Item'}</strong><br/>
                        <span style="font-size: 10px;">${item.description || item.itemId?.description || ''}</span>
                    </td>
                    <td style="width: 16%; text-align: center; padding-right: 15px; vertical-align: top;">${qty}</td>
                    <td style="width: 10%; text-align: center; vertical-align: top;">${gstPerc}%</td>
                    <td style="width: 23%; text-align: right; padding-right: 15px; vertical-align: top;">${totalWithGst.toFixed(2)}</td>
                </tr>
            `;

            taxItemsHtml += `
                <tr style="height: 25px;">
                    <td style="width: 8%; text-align: center;">${index + 1}</td>
                    <td style="width: 32%; padding-left: 10px;">${item.name || item.itemId?.name || 'Item'}</td>
                    <td style="width: 17%; text-align: center;">${valueBeforeGst.toFixed(2)}</td>
                    <td style="width: 16%; text-align: center; padding-right: 15px;">${gstPerc}%</td>
                    <td style="width: 16%; text-align: center; padding-right: 15px;">${gstAmt.toFixed(2)}</td>
                    <td style="width: 17%; text-align: right; padding-right: 15px;">${totalWithGst.toFixed(2)}</td>
                </tr>
            `;
        });

        const totalAmount = calcSubTotal + taxAmount;
        const totalAmountWords = numberToWords(Math.round(totalAmount));

        // TO-DO FOR USER: 
        // Convert the blank estimate image to base64 and paste it here, OR use an absolute URL.
        // E.g. 'data:image/jpeg;base64,/9j/4AAQSkZJRgABAQ...' 
        // You can use a site like https://www.base64-image.de/ to convert your image.
        const backgroundImageUrl = "";

        const htmlContent = `
            <!DOCTYPE html>
            <html>
            <head>
                <meta charset="UTF-8">
                <style>
                    @import url('https://fonts.googleapis.com/css2?family=Roboto:wght@500;700&display=swap');
                    body {
                        margin: 0;
                        padding: 0;
                        font-family: 'Roboto', sans-serif;
                        color: #000;
                        font-size: 13px;
                    }
                    /* Container exactly matches A4 aspect ratio */
                    .a4-container {
                        width: 794px;
                        height: 1122px; 
                        position: relative;
                        background-image: url('data:image/png;base64,${backgroundImageUrl}');
                        background-size: 100% 100%;
                        background-repeat: no-repeat;
                    }
                    
                    /* ABSOLUTE POSITIONED ELEMENTS */
                    .estimate-no { position: absolute; top: 192px; left: 645px; font-weight: bold; font-size: 12px; }
                    .estimate-date { position: absolute; top: 211px; left: 645px; font-weight: bold; font-size: 12px; }
                    
                    .bill-to { position: absolute; top: 233px; left: 95px; font-weight: bold; font-size: 14px; width: 600px;}
                    
                    /* Main Table Data Container */
                    .main-items { position: absolute; top: 305px; left: 25px; width: 743px; }
                    .main-items table { width: 100%; border-collapse: collapse; }
                    .main-items td { border: none; padding-top: 2px; padding-bottom: 2px; }
                    .main-items tr:last-child td { border-bottom: none; }

                    /* Totals A & B */
                    .total-a { position: absolute; top: 925px; left: 600px; width: 160px; text-align: center; font-weight: bold; }
                    .total-b { position: absolute; top: 955px; left: 600px; width: 160px; text-align: center; font-weight: bold; }
                    .total-ab { position: absolute; top: 985px; left: 600px; width: 160px; text-align: center; font-weight: bold; font-size: 18px; }

                    /* Tax Breakup Data Container */
                    .tax-items { position: absolute; top: 850px; left: 25px; width: 743px; }
                    .tax-items table { width: 100%; border-collapse: collapse; }
                    .tax-items td { border: none; padding-top: 2px; padding-bottom: 2px; }
                    .tax-items tr:last-child td { border-bottom: none; }
                    
                    .tax-subtotal { position: absolute; top: 935px; left: 320px; width: 130px; text-align: center; font-weight: bold;}
                    .tax-gst { position: absolute; top: 935px; left: 545px; width: 95px; text-align: center; font-weight: bold;}
                    .tax-total { position: absolute; top: 935px; left: 640px; width: 130px; text-align: right; padding-right:15px; font-weight: bold;}

                    .amount-words { position: absolute; top: 980px; left: 180px; font-weight: bold; font-size: 14px; color: #000; width: 550px;}

                    /* We can leave the signature/warranty empty as it's static in the template image */
                </style>
            </head>
            <body>
                <div class="a4-container">
                    <!-- Overlay Data -->
                    <div class="estimate-no">${quotation.quotationNumber}</div>
                    <div class="estimate-date">${qDate}</div>
                    
                    <div class="bill-to">
                        ${lead.customerName || ''} ${lead.companyName ? ' - ' + lead.companyName : ''}
                    </div>

                    <div class="main-items">
                        <table>
                            ${itemsHtml}
                        </table>
                    </div>

                    <div class="total-a">${productTotal.toFixed(2)}</div>
                    <div class="total-b">${serviceTotal.toFixed(2)}</div>
                    <div class="total-ab">${(quotation.totalAmount || totalAmount || 0).toFixed(2)}</div>

                    <div class="tax-items">
                        <table>
                            ${taxItemsHtml}
                        </table>
                    </div>

                    <div class="tax-subtotal">${calcSubTotal.toFixed(2)}</div>
                    <div class="tax-gst">${taxAmount.toFixed(2)}</div>
                    <div class="tax-total">${(quotation.totalAmount || totalAmount || 0).toFixed(2)}</div>

                    <div class="amount-words">${totalAmountWords}</div>
                </div>
            </body>
            </html>
        `;

        await page.setContent(htmlContent, { waitUntil: 'networkidle0', timeout: 300000 });

        await page.setViewport({ width: 794, height: 1122 });
        const element = await page.$('.a4-container');
        const imageBuffer = await element.screenshot({ type: 'jpeg', quality: 100 });

        await browser.close();
        return imageBuffer;
    } catch (error) {
        console.error("Error generating Image:", error);
        throw error;
    }
};
